import { logAuditAction } from '@/lib/audit'

const UpdateBrandingSchema = z.object({
  custom_domain: z.string().max(253).nullable().optional(),
  white_label_enabled: z.boolean().optional(),
  custom_favicon_url: z.string().url().max(2048).nullable().optional(),
  custom_email_from_name: z.string().max(100).nullable().optional(),
  custom_email_reply_to: z.string().email().max(254).nullable().optional(),
  powered_by_hidden: z.boolean().optional(),
})

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('studios')
      .select(`
        custom_domain, custom_domain_verified, custom_domain_verified_at,
        white_label_enabled, custom_favicon_url, logo_url,
        custom_email_from_name, custom_email_reply_to, powered_by_hidden, brand_color
      `)
      .eq('id', authUser.studioId)
      .single()

