export async function PUT(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (authUser.role !== 'owner') {
    return NextResponse.json({ error: 'Forbidden — owner only' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateBrandingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  // Gate white-label fields to Enterprise
  if (parsed.data.white_label_enabled !== undefined || parsed.data.powered_by_hidden !== undefined) {
    try {
      await requireFeatureRpc(supabase, authUser.studioId, 'white_label')
    } catch (err) {
      if (err instanceof FeatureGateError) {
        return NextResponse.json({ error: 'White-label requires Enterprise plan' }, { status: 403 })
      }
      throw err
    }
  }

  try {
    const { data, error } = await supabase
      .from('studios')
      .update(parsed.data)
      .eq('id', authUser.studioId)
      .select(`
        custom_domain, custom_domain_verified, white_label_enabled,
        custom_favicon_url, custom_email_from_name, custom_email_reply_to, powered_by_hidden
      `)
      .single()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'branding PUT failed')
      return NextResponse.json({ error: 'Failed to update branding' }, { status: 500 })
    }

    await logAuditAction({
      actor_id: authUser.user.id,
      action: 'studio.branding.update',
      target_type: 'studio',
      target_id: authUser.studioId,
      studio_id: authUser.studioId,
      details: parsed.data,
    })

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'branding PUT unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

