import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const RedeemSchema = z.object({
  code: z.string().min(1).max(20),
  booking_id: z.string().uuid(),
  referred_client_id: z.string().uuid(),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = RedeemSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    const { data, error } = await supabase.rpc('redeem_referral', {
      p_code: parsed.data.code,
      p_booking_id: parsed.data.booking_id,
      p_referred_client_id: parsed.data.referred_client_id,
    })

    if (error) {
      logger.error({ err: error }, 'redeem_referral rpc failed')
      const isBusinessError = error.message?.includes('self-referral') ||
        error.message?.includes('expired') ||
        error.message?.includes('max uses')
      return NextResponse.json(
        { error: isBusinessError ? error.message : 'Failed to redeem referral code' },
        { status: isBusinessError ? 422 : 500 }
      )
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'referral redeem unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'

const ConnectSchema = z.object({
  artist_id: z.string().uuid(),
  sync_direction: z.enum(['export', 'import', 'bidirectional']).default('bidirectional'),
})

const GOOGLE_OAUTH_SCOPES = [
  'https://www.googleapis.com/auth/calendar',
  'https://www.googleapis.com/auth/calendar.events',
].join(' ')

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ConnectSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'calendar_sync')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json({ error: 'Google Calendar sync requires Studio plan' }, { status: 403 })
    }
    throw err
  }

  try {
    const clientId = process.env.GOOGLE_OAUTH_CLIENT_ID
    const redirectUri = `${process.env.NEXT_PUBLIC_APP_URL}/api/integrations/google-calendar/callback`

    if (!clientId) {
      logger.error({}, 'GOOGLE_OAUTH_CLIENT_ID not configured')
      return NextResponse.json({ error: 'Google Calendar not configured' }, { status: 503 })
    }

    const state = Buffer.from(
      JSON.stringify({
        artist_id: parsed.data.artist_id,
        studio_id: authUser.studioId,
        sync_direction: parsed.data.sync_direction,
        user_id: authUser.user.id,
        ts: Date.now(),
      })
    ).toString('base64url')

    const authUrl = new URL('https://accounts.google.com/o/oauth2/v2/auth')
    authUrl.searchParams.set('client_id', clientId)
    authUrl.searchParams.set('redirect_uri', redirectUri)
    authUrl.searchParams.set('response_type', 'code')
    authUrl.searchParams.set('scope', GOOGLE_OAUTH_SCOPES)
    authUrl.searchParams.set('access_type', 'offline')
    authUrl.searchParams.set('prompt', 'consent')
    authUrl.searchParams.set('state', state)

    return NextResponse.json({ auth_url: authUrl.toString() })
  } catch (err) {
    logger.error({ err }, 'google calendar connect unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

interface OAuthState {
  artist_id: string
  studio_id: string
  sync_direction: 'export' | 'import' | 'bidirectional'
  user_id: string
  ts: number
}

interface GoogleTokenResponse {
  access_token: string
  refresh_token?: string
  expires_in: number
  token_type: string
}

function isValidState(value: unknown): value is OAuthState {
  return (
    typeof value === 'object' &&
    value !== null &&
    'artist_id' in value &&
    'studio_id' in value &&
    'sync_direction' in value &&
    'user_id' in value &&
    'ts' in value
  )
}

function isTokenResponse(value: unknown): value is GoogleTokenResponse {
  return (
    typeof value === 'object' &&
    value !== null &&
    'access_token' in value &&
    typeof (value as Record<string, unknown>).access_token === 'string'
  )
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const code = searchParams.get('code')
  const stateRaw = searchParams.get('state')
  const error = searchParams.get('error')

  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? ''

  if (error) {
    logger.warn({ error }, 'Google OAuth denied by user')
    return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=denied`)
  }

  if (!code || !stateRaw) {
    return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=missing_params`)
  }

  let state: OAuthState
  try {
    const decoded = JSON.parse(Buffer.from(stateRaw, 'base64url').toString('utf-8'))
    if (!isValidState(decoded)) throw new Error('invalid shape')
    // Reject states older than 10 minutes
    if (Date.now() - decoded.ts > 10 * 60 * 1000) throw new Error('expired')
    state = decoded
  } catch {
    return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=invalid_state`)
  }

  try {
    const clientId = process.env.GOOGLE_OAUTH_CLIENT_ID!
    const clientSecret = process.env.GOOGLE_OAUTH_CLIENT_SECRET!
    const redirectUri = `${appUrl}/api/integrations/google-calendar/callback`

    const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        redirect_uri: redirectUri,
        grant_type: 'authorization_code',
        code,
      }),
    })

    const tokenData: unknown = await tokenRes.json()
    if (!tokenRes.ok || !isTokenResponse(tokenData)) {
      logger.error({ status: tokenRes.status, tokenData }, 'google token exchange failed')
      return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=token_exchange`)
    }

    const expiresAt = new Date(Date.now() + tokenData.expires_in * 1000).toISOString()

    // Use service role to store encrypted tokens
    const supabase = createServiceRoleClient()

    // Tokens stored encrypted via pgcrypto via RPC — never in plaintext
    const { error: upsertError } = await supabase.rpc('store_calendar_tokens', {
      p_studio_id: state.studio_id,
      p_artist_id: state.artist_id,
      p_provider: 'google',
      p_sync_direction: state.sync_direction,
      p_access_token: tokenData.access_token,
      p_refresh_token: tokenData.refresh_token ?? null,
      p_token_expires_at: expiresAt,
    })

    if (upsertError) {
      logger.error({ err: upsertError, artistId: state.artist_id }, 'store_calendar_tokens failed')
      return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=store_failed`)
    }

    await logAuditAction({
      actor_id: state.user_id,
      action: 'integration.google_calendar.connect',
      target_type: 'artist',
      target_id: state.artist_id,
      studio_id: state.studio_id,
      details: { sync_direction: state.sync_direction },
    })

    return NextResponse.redirect(`${appUrl}/settings/integrations?cal_success=1`)
  } catch (err) {
    logger.error({ err }, 'google calendar callback unexpected error')
    return NextResponse.redirect(`${appUrl}/settings/integrations?cal_error=server`)
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

const DisconnectSchema = z.object({
  artist_id: z.string().uuid(),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = DisconnectSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    const { error } = await supabase
      .from('external_calendar_syncs')
      .update({ is_active: false, access_token_encrypted: null, refresh_token_encrypted: null })
      .eq('studio_id', authUser.studioId)
      .eq('artist_id', parsed.data.artist_id)
      .eq('provider', 'google')

    if (error) {
      logger.error({ err: error, artistId: parsed.data.artist_id }, 'google calendar disconnect failed')
      return NextResponse.json({ error: 'Failed to disconnect' }, { status: 500 })
    }

    await logAuditAction({
      actor_id: authUser.user.id,
      action: 'integration.google_calendar.disconnect',
      target_type: 'artist',
      target_id: parsed.data.artist_id,
      studio_id: authUser.studioId,
      details: {},
    })

    return NextResponse.json({ disconnected: true })
  } catch (err) {
    logger.error({ err }, 'google calendar disconnect unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { enqueueJob } from '@/lib/queue'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'

const SyncSchema = z.object({
  artist_id: z.string().uuid(),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'artist'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try { body = await request.json() } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = SyncSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'calendar_sync')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json({ error: 'Calendar sync requires Studio plan' }, { status: 403 })
    }
    throw err
  }

  try {
    // Verify active sync exists
    const { data: sync } = await supabase
      .from('external_calendar_syncs')
      .select('id')
      .eq('studio_id', authUser.studioId)
      .eq('artist_id', parsed.data.artist_id)
      .eq('provider', 'google')
      .eq('is_active', true)
      .maybeSingle()

    if (!sync) {
      return NextResponse.json({ error: 'No active Google Calendar connection found' }, { status: 404 })
    }

    await enqueueJob('sync-calendar', {
      studioId: authUser.studioId,
      artistId: parsed.data.artist_id,
    })

    return NextResponse.json({ queued: true })
  } catch (err) {
    logger.error({ err }, 'google calendar sync unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'

const ExportSchema = z.object({
  type: z.enum(['commissions', 'payroll', 'invoices']),
  from: z.string().datetime(),
  to: z.string().datetime(),
})

const QB_COMMISSION_HEADERS = [
  'Date', 'Artist', 'Client', 'Service', 'Booking Amount', 'Commission %', 'Commission Amount',
  'Payment Method', 'Invoice Number',
]

const QB_PAYROLL_HEADERS = [
  'Pay Period Start', 'Pay Period End', 'Artist', 'Total Hours', 'Hourly Rate',
  'Gross Pay', 'Commission Earned', 'Total Payout', 'Payment Date',
]

const QB_INVOICE_HEADERS = [
  'Invoice Number', 'Date', 'Due Date', 'Client Name', 'Client Email',
  'Description', 'Amount', 'Tax', 'Total', 'Status',
]

function toCSV(headers: string[], rows: string[][]): string {
  const escape = (v: string) => `"${v.replace(/"/g, '""')}"`
  return [
    headers.map(escape).join(','),
    ...rows.map(row => row.map(escape).join(',')),
  ].join('\r\n')
}

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden — owner only' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const parsed = ExportSchema.safeParse({
    type: searchParams.get('type'),
    from: searchParams.get('from'),
    to: searchParams.get('to'),
  })

  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'payroll')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json({ error: 'QuickBooks export requires Pro plan' }, { status: 403 })
    }
    throw err
  }

  try {
    const { type, from, to } = parsed.data
    let csvContent = ''
    const filename = `inkos-${type}-${from.slice(0, 10)}-to-${to.slice(0, 10)}.csv`

    if (type === 'commissions') {
      const { data, error } = await supabase
        .from('commissions')
        .select(`
          created_at, amount_cents, rate_pct, payment_method,
          artist:artists(display_name),
          booking:bookings(id, price_cents, client:clients(first_name, last_name), service:services(name))
        `)
        .eq('studio_id', authUser.studioId)
        .gte('created_at', from)
        .lte('created_at', to)
        .order('created_at', { ascending: true })

      if (error) throw error

      type RawCommission = typeof data extends (infer T)[] | null ? T : never
      function isRecord(v: unknown): v is Record<string, unknown> {
        return typeof v === 'object' && v !== null
      }

      const rows: string[][] = (data ?? []).map((c: RawCommission) => {
        const artist = isRecord(c.artist) ? String(c.artist.display_name ?? '') : ''
        const booking = isRecord(c.booking) ? c.booking : null
        const client = booking && isRecord(booking.client)
          ? `${booking.client.first_name ?? ''} ${booking.client.last_name ?? ''}`.trim()
          : ''
        const service = booking && isRecord(booking.service)
          ? String(booking.service.name ?? '')
          : ''
        const bookingAmount = booking ? String(Number(booking.price_cents) / 100) : '0'
        const commAmount = String(c.amount_cents / 100)
        return [
          String(c.created_at).slice(0, 10),
          artist, client, service,
          bookingAmount,
          String(c.rate_pct),
          commAmount,
          String(c.payment_method ?? 'cash'),
          String(isRecord(c.booking) ? c.booking.id ?? '' : '').slice(0, 8).toUpperCase(),
        ]
      })

      csvContent = toCSV(QB_COMMISSION_HEADERS, rows)
    } else if (type === 'payroll') {
      const { data, error } = await supabase
        .from('payroll_runs')
        .select(`
          period_start, period_end, total_payout_cents, paid_at, status,
          payroll_items(
            gross_pay_cents, commission_cents, hours_worked,
            artist:artists(display_name, hourly_rate_cents)
          )
        `)
        .eq('studio_id', authUser.studioId)
        .gte('period_start', from.slice(0, 10))
        .lte('period_end', to.slice(0, 10))
        .order('period_start', { ascending: true })

      if (error) throw error

      function isRecord(v: unknown): v is Record<string, unknown> {
        return typeof v === 'object' && v !== null
      }

      type RawRun = typeof data extends (infer T)[] | null ? T : never
      const rows: string[][] = []
      for (const run of data ?? []) {
        const typedRun = run as RawRun
        const items = Array.isArray(typedRun.payroll_items) ? typedRun.payroll_items : []
        for (const item of items) {
          if (!isRecord(item)) continue
          const artist = isRecord(item.artist) ? String(item.artist.display_name ?? '') : ''
          const hourlyRate = isRecord(item.artist) && item.artist.hourly_rate_cents
            ? String(Number(item.artist.hourly_rate_cents) / 100)
            : '0'
          rows.push([
            String(typedRun.period_start),
            String(typedRun.period_end),
            artist,
            String(item.hours_worked ?? 0),
            hourlyRate,
            String(Number(item.gross_pay_cents ?? 0) / 100),
            String(Number(item.commission_cents ?? 0) / 100),
            String((Number(item.gross_pay_cents ?? 0) + Number(item.commission_cents ?? 0)) / 100),
            String(typedRun.paid_at ?? '').slice(0, 10),
          ])
        }
      }

      csvContent = toCSV(QB_PAYROLL_HEADERS, rows)
    } else {
      // invoices
      csvContent = toCSV(QB_INVOICE_HEADERS, [])
    }

    return new NextResponse(csvContent, {
      status: 200,
      headers: {
        'Content-Type': 'text/csv; charset=utf-8',
        'Content-Disposition': `attachment; filename="${filename}"`,
      },
    })
  } catch (err) {
    logger.error({ err }, 'quickbooks export unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

